import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"From Context to EDUs: Faithful and Structured Context Compression via Elementary Discourse Unit Decomposition","description":"","frontmatter":{"url":"https://arxiv.org/abs/2512.14244","title":"From Context to EDUs: Faithful and Structured Context Compression via Elementary Discourse Unit Decomposition","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2512.14244,"authors":["Yiqing Zhou","Yu Lei","Shuzheng Si","Qingyan Sun","Wei Wang","Yifei Wu","Hao Wen","Gang Chen","Fanchao Qi","Maosong Sun"],"domains":["cs.CL","cs.AI"],"html":"https://arxiv.org/html/2512.14244v1","pdf_path":"pdfs/2512.14244.pdf","published_date":"2025-12-16T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-12-16-context-to-edus-faithful-structured-compression-2512-14244.md","filePath":"research/papers/2025-12-16-context-to-edus-faithful-structured-compression-2512-14244.md","lastUpdated":1785909234000}'),n={name:"research/papers/2025-12-16-context-to-edus-faithful-structured-compression-2512-14244.md"};function i(s,e,l,c,u,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="from-context-to-edus-faithful-and-structured-context-compression-via-elementary-discourse-unit-decomposition" tabindex="-1">From Context to EDUs: Faithful and Structured Context Compression via Elementary Discourse Unit Decomposition <a class="header-anchor" href="#from-context-to-edus-faithful-and-structured-context-compression-via-elementary-discourse-unit-decomposition" aria-label="Permalink to &quot;From Context to EDUs: Faithful and Structured Context Compression via Elementary Discourse Unit Decomposition&quot;">​</a></h1><p><strong>Authors</strong>: Yiqing Zhou, Yu Lei, Shuzheng Si, Qingyan Sun, Wei Wang, Yifei Wu, Hao Wen, Gang Chen, Fanchao Qi, Maosong Sun <strong>Published</strong>: December 16, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2512.14244" target="_blank" rel="noreferrer">https://arxiv.org/abs/2512.14244</a> · <a href="https://arxiv.org/html/2512.14244v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2512.14244 <strong>Categories</strong>: cs.CL, cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2512.14244" target="_blank" rel="noreferrer">research/papers/pdfs/2512.14244.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>（WebFetch 取得為摘述版，逐字全文未取得；以下為抓取內容）Managing extensive context remains a critical challenge for LLMs, particularly in long-document QA and autonomous agents. The paper presents the EDU-based Context Compressor, which converts text into a structural tree of Elementary Discourse Units while preserving both global organization and local details, via a two-stage approach: transform linear content into EDU-based trees, then select query-relevant components. It introduces StructBench, a manually annotated benchmark of 248 documents, and &quot;achieves state-of-the-art structural prediction accuracy&quot; while outperforming frontier LLMs and reducing computational expenses across downstream applications.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>以 Elementary Discourse Unit（EDU）為壓縮原子單位：先把線性文本轉為 EDU 結構樹（保全域組織 + 局部細節），再按 query 選取相關子樹</li><li>兩階段管線把「壓縮」重構為「結構化分解 + 選擇」，而非端到端改寫——保真來自不改寫只挑選</li><li>發布 StructBench：248 篇人工標注文件的結構預測 benchmark</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>結構預測準確率達 SOTA；在 downstream 應用上勝過 frontier LLM 直接壓縮並降低計算成本</li><li>具體數字：未取得（abstract 摘述未含）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>EDU 樹建構本身有前置成本，短文本場景可能不划算</li><li>benchmark 規模 248 篇、人工標注，領域覆蓋度未知</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「分解-選取而非改寫」正是 <code>.claude/skills/output-compress</code> whitelist 不變式的結構化版本：白名單保留 = 選取原文單位，天然免疫 knowledge overwriting / semantic drift（對照 2602.09789）。</li><li>EDU 粒度可作為分級壓縮（lite/full/ultra）的粒度定義候選——lite 刪整棵低相關子樹、ultra 只留 query 命中 EDU。⚠️ 落地需離線 EDU 分割工具，屬新依賴，需評估。</li></ul>',16)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
